(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=540,keys={},pressed={},touch={};
let mode='title',last=0,time=0,camera=0,shake=0,flash=0,worldTick=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), lerp=(a,b,t)=>a+(b-a)*t;
const platforms=[
 {x:0,y:450,w:620,h:130},{x:700,y:450,w:390,h:130},{x:1170,y:450,w:520,h:130},{x:1770,y:450,w:490,h:130},{x:2320,y:450,w:540,h:130},{x:2920,y:450,w:500,h:130},{x:3480,y:450,w:450,h:130},{x:3990,y:450,w:660,h:130},
 {x:250,y:355,w:145,h:18},{x:505,y:300,w:130,h:18},{x:790,y:365,w:150,h:18},{x:1000,y:310,w:150,h:18},{x:1260,y:350,w:170,h:18},{x:1515,y:295,w:135,h:18},{x:1855,y:360,w:150,h:18},{x:2100,y:305,w:160,h:18},{x:2410,y:355,w:165,h:18},{x:2705,y:300,w:140,h:18},{x:3000,y:360,w:155,h:18},{x:3250,y:300,w:160,h:18},{x:3590,y:355,w:160,h:18},{x:3820,y:295,w:130,h:18},{x:4140,y:345,w:150,h:18}
];
const door={x:2960,y:365,w:62,h:85,open:false};
const shrines=[{x:120,y:409,name:'Umbral de vigilia',active:true},{x:1670,y:409,name:'Capilla sumergida',active:false},{x:2870,y:409,name:'Jardín de espinas',active:false},{x:3960,y:409,name:'Altar del ocaso',active:false}];
const enemySeeds=[{x:440,type:'wisp'},{x:865,type:'hollow'},{x:1050,type:'hollow'},{x:1390,type:'wisp'},{x:1580,type:'hollow'},{x:1960,type:'hollow'},{x:2190,type:'wisp'},{x:2490,type:'hollow'},{x:2780,type:'wisp'},{x:3130,type:'hollow'},{x:3360,type:'hollow'},{x:3670,type:'wisp'},{x:3850,type:'hollow'},{x:4250,type:'hollow'}];
let enemies=[],particles=[],souls=0,deathShade=null,checkpoint=0,killCount=0,ending=false;
const player={x:100,y:400,vx:0,vy:0,w:25,h:42,face:1,hp:5,maxHp:5,stamina:100,attack:0,dodge:0,invuln:0,heal:0,ground:false,anim:0};
const boss={x:4350,y:350,hp:18,maxHp:18,alive:true,phase:0,attack:0,hit:0};
const dust=Array.from({length:100},(_,i)=>({x:(i*193)%4800,y:(i*71)%500,r:.7+(i%5)*.24,s:.14+(i%4)*.12,p:i*2.7}));
function initEnemies(){enemies=enemySeeds.map((e,i)=>({x:e.x,y:e.type==='wisp'?355:409,home:e.x,dir:i%2?1:-1,type:e.type,hp:e.type==='wisp'?2:3,alive:true,alert:0,hit:0,attack:0,cool:0,phase:i*1.7}));}
initEnemies();
function keyName(e){return ({ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',KeyW:'jump',Space:'jump',KeyJ:'attack',KeyK:'dodge',ShiftLeft:'dodge',KeyE:'interact',KeyH:'heal',KeyM:'map',Escape:'pause'})[e.code]}
window.addEventListener('keydown',e=>{const k=keyName(e);if(k){e.preventDefault();if(!keys[k])pressed[k]=true;keys[k]=true;}});
window.addEventListener('keyup',e=>{const k=keyName(e);if(k)keys[k]=false;});
window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false;});
document.querySelectorAll('#mobile button').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();touch[k]=true;pressed[k]=true;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>touch[k]=false)});
function down(k){return !!(keys[k]||touch[k])} function tap(k){return !!pressed[k]}
function startGame(){mode='play';player.x=100;player.y=400;player.vx=player.vy=0;camera=0;}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function glow(x,y,r,color){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'#00000000');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function text(str,x,y,size,color='#e8e4d8',align='left',font='Georgia'){ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(str,x,y)}
function roundRect(x,y,w,h,r,color,stroke=null){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function spawn(x,y,color,n=8,power=2){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:.45+Math.random()*.55,max:.9,size:1+Math.random()*3,color});}}
function worldText(str,x,y,size,color){ctx.save();ctx.translate(x-camera,y);text(str,0,0,size,color,'center');ctx.restore()}
function update(dt){time+=dt;worldTick+=dt;shake=Math.max(0,shake-dt*28);flash=Math.max(0,flash-dt*2.4);
 if(mode==='title'){if(tap('jump')||tap('attack')||tap('interact'))startGame();return}
 if(mode==='dead'){if(tap('jump')||tap('attack')||tap('interact'))respawn();return}
 if(mode==='victory'){if(tap('jump')||tap('attack')){mode='title';ending=false}return}
 if(tap('pause')){mode=mode==='play'?'pause':'play';return}if(mode==='pause'){if(tap('jump')||tap('interact'))mode='play';return}
 const p=player;p.anim+=dt*8;p.invuln=Math.max(0,p.invuln-dt);p.attack=Math.max(0,p.attack-dt);p.dodge=Math.max(0,p.dodge-dt);p.heal=Math.max(0,p.heal-dt);p.stamina=Math.min(100,p.stamina+dt*19);
 const move=(down('right')?1:0)-(down('left')?1:0);if(move&&!p.dodge){p.vx=lerp(p.vx,move*205,Math.min(1,dt*11));p.face=move}else if(!p.dodge)p.vx*=Math.pow(.001,dt);
 if(tap('jump')&&p.ground){p.vy=-475;p.ground=false;spawn(p.x+p.w/2,p.y+p.h,'#b8b2a1',5,1.3)}
 if(tap('dodge')&&p.stamina>=25&&p.dodge<=0){p.stamina-=25;p.dodge=.24;p.invuln=.35;p.vx=p.face*430;spawn(p.x+p.w/2,p.y+25,'#88c9c4',8,2.6)}
 if(tap('attack')&&p.attack<=0&&p.stamina>=12){p.stamina-=12;p.attack=.32;spawn(p.x+p.w/2+p.face*23,p.y+21,'#e7c77b',5,1.6);}
 if(tap('heal')&&p.hp<p.maxHp&&p.stamina>=40){p.stamina-=40;p.hp++;p.heal=.72;p.invuln=.5;spawn(p.x+12,p.y+18,'#75c9aa',18,2.4)}
 p.vy=Math.min(780,p.vy+1250*dt);moveAndCollide(p,dt);
 p.x=clamp(p.x,0,4615);if(p.y>650){die()}
 if(p.attack>0){const ax=p.x+(p.face>0?p.w:-44),ay=p.y+5;for(const e of enemies){if(e.alive&&e.hit<=0&&Math.abs((e.x+14)-(ax+22))<47&&Math.abs(e.y-p.y)<48){e.hp--;e.hit=.25;e.alert=2;spawn(e.x+14,e.y+8,'#e4be71',9,2.2);shake=3;if(e.hp<=0){e.alive=false;killCount++;souls+=e.type==='wisp'?22:30;spawn(e.x+14,e.y,'#c7ae70',17,3)}}}if(boss.alive&&Math.abs((boss.x+25)-(p.x+p.w/2+p.face*35))<66&&Math.abs(boss.y-p.y)<65&&boss.hit<=0){boss.hp--;boss.hit=.24;boss.phase=1;shake=7;spawn(boss.x+25,boss.y+22,'#edc879',14,3);if(boss.hp<=0){boss.alive=false;souls+=200;spawn(boss.x+25,boss.y+22,'#f3d890',36,4);ending=true}}}
 updateEnemies(dt);updateBoss(dt);updateShrines();updateParticles(dt);
 if(deathShade){deathShade.life-=dt;if(deathShade.life<=0)deathShade=null;if(Math.abs(p.x-deathShade.x)<40&&Math.abs(p.y-deathShade.y)<65&&tap('interact')){souls+=deathShade.souls;spawn(deathShade.x,deathShade.y,'#9b8ddd',24,3);deathShade=null}}
 if(p.x>4530&&!boss.alive){mode='victory'}
 camera=lerp(camera,clamp(p.x-390,0,4615-W),Math.min(1,dt*4.5));
}
function moveAndCollide(o,dt){o.x+=o.vx*dt;for(const b of platforms){if(overlap(o,b)){if(o.vx>0)o.x=b.x-o.w;else if(o.vx<0)o.x=b.x+b.w;o.vx=0}}
 o.y+=o.vy*dt;o.ground=false;for(const b of platforms){if(overlap(o,b)){if(o.vy>0){o.y=b.y-o.h;o.ground=true}else if(o.vy<0)o.y=b.y+b.h;o.vy=0}}
}
function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function hurt(amount,from){const p=player;if(p.invuln||p.dodge)return;p.hp-=amount;p.invuln=.85;p.vx=(p.x<from?-1:1)*260;p.vy=-190;shake=10;flash=.42;spawn(p.x+12,p.y+20,'#b94748',14,3);if(p.hp<=0)die()}
function die(){if(mode!=='play')return;deathShade={x:player.x,y:player.y,souls,life:100};souls=0;mode='dead';player.hp=0;}
function respawn(){mode='play';const s=shrines[checkpoint];player.x=s.x+45;player.y=390;player.vx=player.vy=0;player.hp=player.maxHp;player.stamina=100;player.invuln=1.2;camera=clamp(player.x-390,0,4615-W);}
function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;e.hit=Math.max(0,e.hit-dt);e.cool=Math.max(0,e.cool-dt);const d=player.x-e.x,dist=Math.abs(d);if(dist<260)e.alert=Math.min(3,e.alert+dt);else e.alert=Math.max(0,e.alert-dt);if(e.type==='hollow'){
 if(e.alert>0&&dist<170){e.dir=Math.sign(d)||e.dir;e.x+=e.dir*(e.alert>1.3?65:95)*dt}else{e.x+=e.dir*25*dt;if(Math.abs(e.x-e.home)>72)e.dir*=-1}
 e.y=409;if(dist<33&&Math.abs(player.y-e.y)<44&&e.cool<=0){e.cool=.95;hurt(1,e.x+14)}
 }else{e.phase+=dt*2;e.x=e.home+Math.sin(e.phase)*35;e.y=340+Math.sin(e.phase*1.3)*18;if(dist<200&&e.cool<=0){e.cool=1.8;e.attack=.6}if(e.attack>0){e.attack-=dt;if(e.attack<.22&&dist<30&&Math.abs(player.y-e.y)<45)hurt(1,e.x)}}}}
function updateBoss(dt){if(!boss.alive)return;boss.hit=Math.max(0,boss.hit-dt);boss.phase+=dt;boss.attack-=dt;const d=player.x-boss.x;if(Math.abs(d)<320)boss.x+=Math.sign(d)*Math.min(45*dt,Math.abs(d)-95);if(boss.attack<=0&&Math.abs(d)<250){boss.attack=2.2;boss.phase=0}if(boss.attack<.42&&boss.attack>0&&Math.abs(player.x-boss.x)<95&&Math.abs(player.y-boss.y)<80)hurt(2,boss.x);}
function updateShrines(){for(let i=0;i<shrines.length;i++){const s=shrines[i];if(Math.abs(player.x-s.x)<65&&Math.abs(player.y-s.y)<95){if(tap('interact')){checkpoint=i;shrines.forEach((v,j)=>v.active=j===i);player.hp=player.maxHp;player.stamina=100;spawn(s.x+20,s.y-32,'#8bd6cd',24,2.5)}if(tap('heal')&&souls>=100&&player.maxHp<8){souls-=100;player.maxHp++;player.hp=player.maxHp;spawn(s.x+20,s.y-32,'#e8cc80',28,3)}}}}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.life-=dt;a.x+=a.vx;a.y+=a.vy;a.vy+=35*dt;a.vx*=.98;if(a.life<=0)particles.splice(i,1)}}

