function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.life-=dt;a.x+=a.vx;a.y+=a.vy;a.vy+=35*dt;a.vx*=.98;if(a.life<=0)particles.splice(i,1)}}
function draw(){ctx.save();if(shake)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawSky();ctx.save();ctx.translate(-camera,0);drawScenery();drawPlatforms();drawDoor();drawShrines();drawEnemies();drawBoss();drawShade();drawPlayer();drawParticles();ctx.restore();drawHud();if(flash){rect(0,0,W,H,`rgba(151,35,39,${flash*.38})`)}if(mode==='title')drawTitle();if(mode==='dead')drawDead();if(mode==='pause')drawPause();if(mode==='victory')drawVictory();ctx.restore()}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#111a22');g.addColorStop(.58,'#17232a');g.addColorStop(1,'#0c1218');rect(0,0,W,H,g);glow(770,145,240,'#c7a86a12');ctx.fillStyle='#d5c9a322';ctx.beginPath();ctx.arc(755,128,45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#131c22';ctx.beginPath();ctx.arc(775,117,43,0,Math.PI*2);ctx.fill();
 // layered distant ridges
 for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(0,H);const par=camera*(.08+layer*.09);for(let x=-100;x<=W+120;x+=110){const wx=x+par;const y=270+layer*42+Math.sin(wx*.008+layer)*32+Math.sin(wx*.023)*17;ctx.lineTo(x,y);ctx.lineTo(x+55,y-70-(layer===2?20:0));ctx.lineTo(x+110,y+8)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#172228','#111b21','#0e171c'][layer];ctx.fill()}
 for(const d of dust){const x=(d.x-camera*d.s+4800)%4800-camera*.1;if(x>-5&&x<W+5){ctx.globalAlpha=.2+Math.sin(time*1.5+d.p)*.12;ctx.fillStyle='#d8cfaa';ctx.fillRect(x,d.y+Math.sin(time+d.p)*5,d.r,d.r)} }ctx.globalAlpha=1;
 // distant watchtowers
 for(let i=0;i<8;i++){const wx=i*640+300,sx=wx-camera*.27;if(sx>-150&&sx<W+150){rect(sx,210,28,185,'#11191e');rect(sx-8,205,44,12,'#1c292d');rect(sx+7,155,14,54,'#11191e');ctx.fillStyle='#c89d60';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(sx+14,229,2,0,7);ctx.fill();ctx.globalAlpha=1}}}
function drawScenery(){for(let i=0;i<20;i++){const x=i*245+48,y=450; if(x<camera-80||x>camera+W+80)continue;const h=65+(i*47)%110;rect(x,y-h,20,h,'#10181d');rect(x-9,y-h-9,38,12,'#1b2629');rect(x+5,y-h-28,10,20,'#121b1f');if(i%3===0){glow(x+9,y-h+20,26,'#d7ad5b10');rect(x+8,y-h+17,2,6,'#a7814a55')}}
 // hanging roots and foreground bones
 for(let i=0;i<14;i++){const x=i*365+185;if(x<camera-50||x>camera+W+50)continue;ctx.strokeStyle='#25302d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,0);ctx.bezierCurveTo(x-15,50,x+17,85,x-2,133+(i%3)*25);ctx.stroke();for(let j=0;j<3;j++){line(x+j*5-5,110+j*12,x+j*6,130+j*17,'#24302e',1)}}}
function drawPlatforms(){for(const p of platforms){if(p.x+p.w<camera-30||p.x>camera+W+30)continue;const ground=p.y>=440;const grad=ctx.createLinearGradient(0,p.y,0,p.y+p.h);grad.addColorStop(0,ground?'#303a37':'#34403d');grad.addColorStop(1,'#161f21');rect(p.x,p.y,p.w,p.h,grad);rect(p.x,p.y,p.w,5,ground?'#768071':'#728078');rect(p.x,p.y+5,p.w,2,'#b1aa8c26');for(let x=p.x+9;x<p.x+p.w-5;x+=37){const n=(Math.sin(x*3.1)*12)|0;line(x,p.y+11,x+7,p.y+22+n,'#121a1c',2);line(x+19,p.y+28,x+24,p.y+34,'#8190822b',1)}if(ground){for(let x=p.x+20;x<p.x+p.w;x+=85){rect(x,p.y-4,2,5,'#91a18b');rect(x+5,p.y-2,1,3,'#798777')}}}}
function drawDoor(){const d=door;roundRect(d.x,d.y,d.w,d.h,3,'#151e20','#796948');rect(d.x+8,d.y+9,d.w-16,d.h-10,'#202727');for(let i=0;i<4;i++)line(d.x+12+i*12,d.y+8,d.x+12+i*12,d.y+d.h-4,'#a58a5533',2);if(!boss.alive){glow(d.x+30,d.y+43,80,'#8bd7c844');rect(d.x+8,d.y+9,d.w-16,d.h-10,'#8bd7c833');text('✦',d.x+30,d.y+54,22,'#bbebd9','center')}else{glow(d.x+30,d.y+43,38,'#b98a3820');text('✧',d.x+30,d.y+54,18,'#b79a5b','center')}}
function drawShrines(){for(const s of shrines){const x=s.x+18,y=s.y-10;glow(x,y-38,s.active?62:36,s.active?'#83cfc432':'#c3a36a18');rect(x-11,y-6,23,9,'#50544a');rect(x-8,y-16,16,10,'#343c38');ctx.beginPath();ctx.moveTo(x-5,y-16);ctx.lineTo(x-4,y-42);ctx.lineTo(x+5,y-42);ctx.lineTo(x+6,y-16);ctx.closePath();ctx.fillStyle='#6c705f';ctx.fill();ctx.strokeStyle='#b9ac7b';ctx.stroke();ctx.beginPath();ctx.arc(x,y-38,5+Math.sin(time*3)*1.5,0,Math.PI*2);ctx.fillStyle=s.active?'#9cddd0':'#b89b63';ctx.fill();if(s.active){ctx.globalAlpha=.65;line(x,y-48,x,y-70,'#9bdbca',2);ctx.globalAlpha=1}if(Math.abs(player.x-s.x)<100){worldText('E  ·  AVIVAR',s.x+18,s.y-82,11,'#e5d7a9');worldText('H  ·  + VIDA  (100 almas)',s.x+18,s.y-65,10,'#b7b29d')}}}
function drawEnemies(){for(const e of enemies){if(!e.alive)continue;const x=e.x,y=e.y;if(e.type==='hollow'){glow(x+14,y+16,42,e.alert?'#d18b5240':'#9d71631c');ctx.save();ctx.translate(x+14,y);if(e.dir<0)ctx.scale(-1,1);ctx.fillStyle=e.hit?'#e7d4a2':'#34383a';ctx.beginPath();ctx.moveTo(-11,7);ctx.quadraticCurveTo(-17,-9,-5,-22);ctx.lineTo(1,-29);ctx.lineTo(8,-21);ctx.quadraticCurveTo(18,-12,12,8);ctx.lineTo(18,30);ctx.lineTo(-16,30);ctx.closePath();ctx.fill();ctx.fillStyle='#14191b';ctx.fillRect(-8,-20,17,5);ctx.fillStyle='#cf9e62';ctx.fillRect(4,-18,4,2);line(-7,1,-17,13,'#6a6251',4);line(7,2,18,14,'#635a4b',3);ctx.restore();}else{const y2=y+Math.sin(time*4+e.phase)*4;glow(x+14,y2,36,'#9cd4d03a');ctx.fillStyle='#789e9a';ctx.beginPath();ctx.ellipse(x+14,y2,10,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d3e2be';ctx.fillRect(x+10,y2-2,2,2);ctx.fillRect(x+16,y2-2,2,2);for(let j=0;j<3;j++){ctx.globalAlpha=.4;ctx.fillRect(x+5+j*8,y2+12+j*4,2,4);ctx.globalAlpha=1}}if(e.alert>.5){text('!',x+14,y-34,12,'#e4bf79','center')}}}

